  "pricing.faq.cancelA": "Ναι! Μπορείτε να ακυρώσετε τη συνδρομή σας οποιαδήποτε στιγμή από τις ρυθμίσεις σας. Αν την ακυρώσετε, παραμένει ενεργή έως το τέλος της τρέχουσας περιόδου - δεν χάνετε τίποτα.",
  "pricing.faq.cancelQ": "Μπορώ να ακυρώσω τη συνδρομή μου οποιαδήποτε στιγμή;",
  "pricing.faq.limitA": "Όχι! Μπορείτε να έχετε απεριόριστους μαθητές. Πληρώνετε μόνο τη συνδρομή και όχι ανά μαθητή.",
  "pricing.faq.limitQ": "Υπάρχει όριο μαθητών;",
  "pricing.faq.paymentA": "Δεχόμαστε όλες τις κύριες πιστωτικές και χρεωστικές κάρτες μέσω Stripe. Το Stripe εξασφαλίζει ασφαλείς πληρωμές με προστασία 3D Secure.",
  "pricing.faq.paymentQ": "Ποιοι τρόποι πληρωμής γίνονται δεκτοί;",
  "pricing.faq.switchA": "Ναι! Μπορείτε να αλλάξετε από μηνιαίο σε ετήσιο πρόγραμμα (και αντίστροφα) οποιαδήποτε στιγμή μέσω της πύλης πελατών Stripe. Η αλλαγή ισχύει από τον επόμενο κύκλο χρέωσης.",
  "pricing.faq.switchQ": "Μπορώ να αλλάξω πρόγραμμα αργότερα;",
  "pricing.faq.trialA": "Κάθε νέος λογαριασμός αποκτά αυτόματα δωρεάν δοκιμή 7 ημερών - χωρίς κωδικό. Θα χρειαστεί να εισαγάγετε στοιχεία κάρτας, αλλά δεν θα χρεωθείτε για 7 ημέρες. Μετά τις 7 ημέρες, η συνδρομή ξεκινά αυτόματα. Μπορείτε να ακυρώσετε οποιαδήποτε στιγμή κατά τη δοκιμή.",
  "pricing.faq.trialQ": "Πώς λειτουργεί η δωρεάν δοκιμή 7 ημερών;",
