  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Ερωτήσεις ή προβλήματα; Επικοινωνήστε στο <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Η επιστροφή χρημάτων σας ξεκίνησε μέσω Stripe.</p><p class=\"text-emerald-800 mt-1\">Οι επιστροφές σε κάρτα συνήθως εμφανίζονται εντός περίπου <strong>5–10 εργάσιμων ημερών</strong> (ο χρόνος διαφέρει ανά τράπεζα). Αν δεν λάβετε το ποσό στο συνηθισμένο διάστημα, στείλτε email στο <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Αυτό το μάθημα δεν φαίνεται να πληρώθηκε μέσω του Stripe του Tutlio (π.χ. τραπεζική μεταφορά ή μετρητά). Δεν υπάρχει αυτόματη επιστροφή εδώ.</p><p class=\"mt-2\">Για να κανονίσετε επιστροφή χρημάτων, επικοινωνήστε με τον καθηγητή σας <strong>{tutor}</strong> — χρησιμοποιήστε το email ή τα στοιχεία από τις κρατήσεις σας ή ζητήστε τα απευθείας από τον καθηγητή.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Αυτό το μάθημα δεν φαίνεται να πληρώθηκε μέσω του Stripe του Tutlio (π.χ. τραπεζική μεταφορά ή μετρητά). Δεν υπάρχει αυτόματη επιστροφή εδώ.</p><p class=\"mt-2\">Επειδή παρακολουθείτε μαθήματα μέσω οργανισμού, επικοινωνήστε με τον <strong>διαχειριστή του οργανισμού</strong> (μέσω του καθηγητή σας ή των δημοσιευμένων στοιχείων επικοινωνίας του οργανισμού).</p>",
  "stuSess.refundTutorFallback": "τον καθηγητή σας",
