  "landing.heroSubtitle": "Βελτιώστε τη λειτουργία της επιχείρησής σας, πάρτε καλύτερες αποφάσεις και αυξήστε την αποδοτικότητα με εξυπνότερη διαχείριση ιδιαίτερων μαθημάτων.",
