  "landing.stepsTitle": "Ξεκινήστε σε 3 απλά βήματα",
  "landing.stepsDesc": "Απλοποιήστε τη διαχείριση των ιδιαίτερων μαθημάτων σας: ρυθμίστε το προφίλ σας, οργανώστε μαθήματα και αναπτύξτε την επιχείρησή σας - με έξυπνους αυτοματισμούς.",
  "landing.step1Title": "Δημιουργήστε το προφίλ σας",
  "landing.step1Desc": "Ρυθμίστε τον χώρο εργασίας σας ως καθηγητής, προσθέστε διδακτικά αντικείμενα, τιμές και διαθεσιμότητα. Προσκαλέστε μαθητές, ώστε όλοι να έχουν κοινή, ενημερωμένη εικόνα.",
  "landing.step2Title": "Οργανώστε τα μαθήματά σας",
  "landing.step2Desc": "Χρησιμοποιήστε το ημερολόγιο, τη λίστα αναμονής και το σύστημα κρατήσεων για να οργανώσετε τα μαθήματα, να καλύψετε κενά και να διαχειρίζεστε το πρόγραμμά σας από την αρχή έως το τέλος.",
  "landing.step3Title": "Πληρωθείτε και αναπτυχθείτε",
  "landing.step3Desc": "Παρακολουθήστε πληρωμές, στείλτε τιμολόγια και ελέγξτε τα οικονομικά σας. Πετύχετε αποτελέσματα γρηγορότερα με σαφή και ακριβή δεδομένα για την επιχείρησή σας.",
  "landing.featuresBadge": "Λειτουργίες",
  "landing.featuresHeading": "Βελτιώστε την επιχείρηση ιδιαίτερων μαθημάτων σας με ",
  "landing.featuresHighlight": "έξυπνα εργαλεία",
  "landing.featuresSubtitle": "Η πλατφόρμα μας σας δίνει εργαλεία για τον προγραμματισμό, τη διαχείριση και την ανάπτυξη της επιχείρησης ιδιαίτερων μαθημάτων σας, ώστε να παίρνετε καλύτερες αποφάσεις και να αυξάνετε την αποδοτικότητα.",
  "landing.feat.scheduling": "Έξυπνος προγραμματισμός",
  "landing.feat.schedulingDesc": "Αφήστε τους μαθητές να κλείνουν τις ώρες που ορίζετε και διαχειριστείτε εύκολα το ημερολόγιό σας.",
