  "landing.feat.schedulingB2": "Ορίστε προθεσμίες κράτησης και αυτόματα διαλείμματα μεταξύ μαθημάτων.",
  "landing.feat.schedulingB3": "Δείτε ολόκληρο το εβδομαδιαίο και μηνιαίο ημερολόγιό σας με όλα τα μαθήματα σε ένα σημείο.",
