  "pwa.guideIntro": "Μπορείτε να προσθέσετε το Tutlio στην αρχική οθόνη του τηλεφώνου σας και να το χρησιμοποιείτε όπως μια κανονική εφαρμογή — σε πλήρη οθόνη και με γρήγορη πρόσβαση.",
  "pwa.iosStep1": "Ανοίξτε το Tutlio στο Safari και πατήστε το κουμπί κοινής χρήσης (τετράγωνο με βέλος) στο κάτω μέρος της οθόνης.",
