  "quiz.intro.solo.title": "Ο χρόνος σας αξίζει περισσότερο στο μάθημα, όχι στη διαχείριση",
  "quiz.intro.solo.body": "Μια ατομική επιχείρηση ιδιαίτερων μαθημάτων μπορεί να φαίνεται απλή απ' έξω, όμως κάθε μαθητής προσθέτει προγραμματισμό, πληρωμές, σημειώσεις, υπενθυμίσεις και μηνύματα.",
