  "quiz.info.insight.school.point2": "Τα προγράμματα δόσεων χρειάζονται σαφή σύνδεση με τον σωστό πληρωτή και το σωστό συμφωνητικό.",
  "quiz.info.insight.school.point3": "Τα οικονομικά δεδομένα γίνονται πιο χρήσιμα όταν είναι ήδη οργανωμένα για αναφορές.",
  "quiz.visual.demoTitle": "Δείτε τον χώρο εργασίας Tutlio στην πράξη",
  "quiz.visual.demoSubtitle.solo": "Ζωντανή περιήγηση στο ημερολόγιο, τις παρουσίες, τις πληρωμές, τα τιμολόγια και τη δημόσια σελίδα καθηγητή σας.",
  "quiz.visual.demoSubtitle.company": "Ζωντανή περιήγηση στα στατιστικά ομάδας, τον φόρτο καθηγητών, τις πληρωμές, τα μηνύματα και την πρόσβαση γονέων.",
  "quiz.visual.demoSubtitle.school": "Ζωντανή περιήγηση στα κεντρικά αρχεία, τις πληρωμές, την επικοινωνία και την πρόσβαση οικογενειών.",
  "quiz.info.story.disclosure": "Ενδεικτική ροή εργασίας - δεν αποτελεί δήλωση πελάτη",
  "quiz.info.story.solo.eyebrow": "Εμπειρίες καθηγητών",
  "quiz.info.story.solo.title": "Λιγότερη διαχείριση, περισσότερη ηρεμία πριν από κάθε μάθημα",
  "quiz.info.story.solo.body": "Δύο σύντομα παραδείγματα για το πώς ένας ενιαίος χώρος εργασίας μπορεί να αλλάξει την εβδομάδα ενός ανεξάρτητου καθηγητή.",
  "quiz.info.story.solo.disclosure": "Ενδεικτικές εμπειρίες καθηγητών",
  "quiz.info.story.solo.name1": "Rasa",
  "quiz.info.story.solo.role1": "Καθηγητής μαθηματικών",
  "quiz.info.story.solo.story1": "«Όταν τα μαθήματα, οι πληροφορίες μαθητών και οι πληρωμές βρίσκονται σε ένα σημείο, δεν περνώ πλέον το βράδυ της Παρασκευής ανασυνθέτοντας την εβδομάδα από μηνύματα.»",
  "quiz.info.story.solo.name2": "Mantas",
  "quiz.info.story.solo.role2": "Καθηγητής αγγλικών",
  "quiz.info.story.solo.story2": "«Ένα ξεκάθαρο ημερολόγιο και οι υπενθυμίσεις με αφήνουν να εστιάζω στην προετοιμασία καλών μαθημάτων, αντί να επαναλαμβάνω την ίδια διαχείριση.»",
  "quiz.info.story.solo.ratingLabel": "5 στα 5 αστέρια",
  "quiz.info.story.company.eyebrow": "Από πελάτη του Tutlio",
  "quiz.info.story.company.title": "Τι άλλαξε για την ομάδα PRO KLASĖ",
  "quiz.info.story.company.body": "Η οργάνωσή τους συνδέει τον προγραμματισμό, την παρακολούθηση μαθημάτων και τους εξατομικευμένους κανόνες αμοιβής σε μία καθημερινή ροή εργασίας.",
  "quiz.info.story.company.disclosure": "Ροή εργασίας πελάτη",
  "quiz.info.story.company.brandAlt": "Λογότυπο PRO KLASĖ",
  "quiz.info.story.company.customerName": "PRO KLASĖ",
  "quiz.info.story.company.customerType": "Ομάδα οργανισμού ιδιαίτερων μαθημάτων",
  "quiz.info.story.company.story": "«Πριν από το Tutlio, οι αλλαγές μαθημάτων, τα σχόλια και οι ώρες καθηγητών ήταν διάσπαρτα σε μηνύματα. Τώρα όλη η ομάδα δουλεύει με το ίδιο πρόγραμμα και δεν χρειάζεται να κυνηγάμε ενημερώσεις στο τέλος του μήνα.»",
  "quiz.info.story.company.proof1": "Προγραμματισμός ομάδας",
  "quiz.info.story.company.proof2": "Εξατομικευμένοι κανόνες αμοιβής",
  "quiz.info.story.company.proof3": "Εποπτεία μαθημάτων",
  "quiz.info.story.company.detail": "«Η μεγαλύτερη διαφορά ήταν ότι οι εγκρίσεις, τα μαθήματα αναπλήρωσης και οι κανόνες αμοιβής προσαρμόστηκαν στον τρόπο που ήδη εργάζεται η ομάδα μας, αντί να μας επιβάλλεται μια γενική διαδικασία.»",
  "quiz.info.story.school.eyebrow": "Από πελάτη του Tutlio",
  "quiz.info.story.school.title": "Τι άλλαξε για τη VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.body": "Η ομάδα τους συνδέει αρχεία μαθητών, συμφωνητικά, δόσεις και λογιστήριο σε μία ενιαία διαδικασία διαχείρισης.",
  "quiz.info.story.school.disclosure": "Ροή εργασίας πελάτη",
  "quiz.info.story.school.brandAlt": "Λογότυπο VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerName": "VšĮ “Laisvi vaikai”",
  "quiz.info.story.school.customerType": "Ομάδα διοίκησης σχολής",
  "quiz.info.story.school.story": "«Θέλαμε ένα σημείο όπου η ομάδα θα μπορούσε να παρακολουθεί μια οικογένεια από την εγγραφή και το συμφωνητικό έως κάθε δόση. Το Tutlio μας δίνει αυτή τη συνέχεια χωρίς να συντηρούμε παράλληλα υπολογιστικά φύλλα.»",
  "quiz.info.story.school.proof1": "Συμφωνητικά και υπογραφές",
  "quiz.info.story.school.proof2": "Προγράμματα δόσεων",
  "quiz.info.story.school.proof3": "Εξαγωγές για το λογιστήριο",
  "quiz.info.story.school.detail": "«Η πιο ξεκάθαρη βελτίωση είναι ότι βλέπουμε την κατάσταση σύμβασης, υπογραφής και πληρωμής χωρίς να ρωτάμε πολλά άτομα ή να ελέγχουμε ξεχωριστά αρχεία.»",
  "quiz.businessCard.eyebrow": "Η ενσωματωμένη σελίδα ανάπτυξής σας",
  "quiz.businessCard.title": "Μετατρέψτε έναν σύνδεσμο σε επαγγελματική πρώτη εντύπωση - και σε κράτηση μαθήματος",
  "quiz.businessCard.body": "Η ψηφιακή επαγγελματική κάρτα Tutlio δίνει στους ενδιαφερόμενους μαθητές ένα σαφές σημείο για να κατανοήσουν τι προσφέρετε, να δουν διαθέσιμες ώρες και να κλείσουν μάθημα.",
