  "quiz.feature.tutorPay.desc": "Συνδέστε κατάσταση μαθημάτων, ώρες, τιμές, προσαρμογές και προετοιμασία τιμολογίων.",
  "quiz.feature.billing.title": "Χρέωση συνδεδεμένη με τα πραγματικά μαθήματα",
