  "quiz.feature.contracts.title": "Ψηφιακές συμβάσεις με ορατή κατάσταση",
  "quiz.feature.contracts.desc": "Δημιουργήστε, στείλτε, υπογράψτε, παρακολουθήστε και αρχειοθετήστε συμφωνητικά σχολής σε μία ροή εργασίας.",
  "quiz.feature.installments.title": "Δόσεις που οι γονείς μπορούν εύκολα να παρακολουθούν",
