  "quiz.feature.companyFinance.title": "Αμοιβές καθηγητών και οικονομικά επιχείρησης υπό έλεγχο",
  "quiz.feature.companyFinance.desc": "Συνδέστε παραδοθέντα μαθήματα, ώρες καθηγητών, προμήθειες, προσαρμογές και προετοιμασία τιμολογίων.",
  "quiz.feature.schoolRecords.title": "Αρχεία σχολής οργανωμένα γύρω από τον μαθητή",
  "quiz.feature.schoolRecords.desc": "Διατηρήστε πλήρες διοικητικό ιστορικό από την εγγραφή έως τη σύμβαση και την πληρωμή.",
  "quiz.feature.parentFlow.title": "Πιο ξεκάθαρη διαδικασία για γονείς",
  "quiz.feature.parentFlow.desc": "Κάντε ευκολότερη την παρακολούθηση υπογραφών, προγραμμάτων πληρωμής, υπενθυμίσεων και βασικών πληροφοριών.",
  "quiz.feature.schoolOversight.title": "Εποπτεία συμφωνητικών, δόσεων και αναφορών σε ένα σημείο",
  "quiz.feature.schoolOversight.desc": "Παρακολουθήστε τις καταστάσεις διαχείρισης και ετοιμάστε δομημένες οικονομικές εξαγωγές χωρίς χειροκίνητη ανασύνθεση δεδομένων.",
  "quiz.feature.schoolFinance.title": "Εξαγωγές έτοιμες για το λογιστήριο χωρίς νέα υπολογιστικά φύλλα",
  "quiz.feature.schoolFinance.desc": "Φιλτράρετε πληρωμές σχολής και ετοιμάστε δομημένες συνόψεις για το λογιστήριο από τα ίδια αρχικά δεδομένα.",
