  "quiz.offer.testimonials.eyebrow": "Το Tutlio στην καθημερινή εργασία",
  "quiz.offer.testimonials.title.solo": "Τι παρατηρούν οι ανεξάρτητοι καθηγητές",
  "quiz.offer.testimonials.title.company": "Πώς υποστηρίζει το Tutlio έναν οργανισμό ιδιαίτερων μαθημάτων",
  "quiz.offer.testimonials.title.school": "Πώς συνδέει το Tutlio τη διαχείριση σχολής",
  "quiz.offer.testimonials.pause": "Παύση μαρτυριών",
  "quiz.offer.testimonials.play": "Αναπαραγωγή μαρτυριών",
  "quiz.offer.testimonials.navigation": "Επιλέξτε μαρτυρία",
  "quiz.offer.testimonials.goTo": "Εμφάνιση μαρτυρίας {number}",
  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Καθηγητής χημείας και βιολογίας",
  "quiz.offer.testimonial.solo.copy3": "«Μια δημόσια σελίδα και η κράτηση μέσω ενός συνδέσμου βοηθούν τους νέους μαθητές να αποφασίσουν γρηγορότερα, ενώ εγώ δεν χρειάζεται πλέον να στέλνω τις ίδιες πληροφορίες ξεχωριστά σε όλους.»",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Καθηγητής φυσικής",
  "quiz.offer.testimonial.solo.copy4": "«Βλέπω αμέσως τα μαθήματα, τις αλλαγές και την κατάσταση πληρωμών στο ημερολόγιο. Η καθημερινή διαχείριση έχει γίνει πολύ συντομότερη και πιο ξεκάθαρη.»",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "Ομάδα οργανισμού ιδιαίτερων μαθημάτων",
  "quiz.offer.testimonial.company.copy1": "«Οι αλλαγές μαθημάτων, τα σχόλια καθηγητών και οι ώρες έφταναν παλιότερα με ξεχωριστά μηνύματα. Τώρα η διοικητική ομάδα βλέπει ολόκληρη την εικόνα σε ένα πρόγραμμα.»",
  "quiz.offer.testimonial.company.name2": "Ανεξάρτητο φροντιστήριο",
  "quiz.offer.testimonial.company.role2": "Ιδιοκτήτης · 8 καθηγητές",
  "quiz.offer.testimonial.company.copy2": "«Περνούσα τα βράδια της Παρασκευής συγκρίνοντας το ημερολόγιο με τα μηνύματα καθηγητών πριν ετοιμάσω τις αμοιβές. Με το Tutlio, το μεγαλύτερο μέρος αυτού του ελέγχου έχει ήδη γίνει.»",
  "quiz.offer.testimonial.company.name3": "Κέντρο ιδιαίτερων μαθημάτων ξένων γλωσσών",
  "quiz.offer.testimonial.company.role3": "Υπεύθυνος λειτουργίας · 14 καθηγητές",
  "quiz.offer.testimonial.company.copy3": "«Όταν μεταφέρεται ένα μάθημα, η ομάδα βλέπει αμέσως την ίδια ενημέρωση. Έχουμε λιγότερα συμπληρωματικά μηνύματα και οι γονείς παίρνουν πολύ πιο ξεκάθαρες απαντήσεις.»",
  "quiz.offer.testimonial.company.name4": "Ακαδημία προετοιμασίας εξετάσεων",
  "quiz.offer.testimonial.company.role4": "Υπεύθυνος οικονομικών · 22 καθηγητές",
  "quiz.offer.testimonial.company.copy4": "«Οι κανόνες αμοιβής μας διαφέρουν ανά τύπο μαθήματος, οπότε το τέλος του μήνα απαιτούσε πολλούς χειροκίνητους ελέγχους. Η ροή εργασίας του Tutlio έκανε αυτή τη διαδικασία πολύ πιο ήρεμη.»",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "Ομάδα διοίκησης σχολής",
  "quiz.offer.testimonial.school.copy1": "«Η πιο ξεκάθαρη βελτίωση είναι ότι βλέπουμε την κατάσταση σύμβασης, υπογραφής και πληρωμής χωρίς να ρωτάμε πολλά άτομα ή να ελέγχουμε ξεχωριστά αρχεία.»",
  "quiz.offer.testimonial.school.name2": "Ανεξάρτητη κοινοτική σχολή",
  "quiz.offer.testimonial.school.role2": "Υπεύθυνος εγγραφών · 86 μαθητές",
  "quiz.offer.testimonial.school.copy2": "«Η περίοδος εγγραφών σήμαινε παρακολούθηση εντύπων, στοιχείων γονέων και υπογεγραμμένων συμφωνητικών σε ξεχωριστούς φακέλους. Τώρα η ομάδα μας παρακολουθεί κάθε οικογένεια από ένα σημείο.»",
  "quiz.offer.testimonial.school.name3": "Κέντρο απογευματινής μάθησης",
  "quiz.offer.testimonial.school.role3": "Διαχειριστής · 120 μαθητές",
  "quiz.offer.testimonial.school.copy3": "«Τα προγράμματα δόσεων έκαναν την παρακολούθηση πληρωμών πολύ πιο ήρεμη. Βλέπω τι οφείλεται πριν επικοινωνήσω με έναν γονέα, αντί να φτιάχνω ξανά τη λίστα χειροκίνητα.»",
  "quiz.offer.testimonial.school.name4": "Σχολή καλλιτεχνικής εκπαίδευσης",
  "quiz.offer.testimonial.school.role4": "Υπεύθυνος οικονομικών · 9 προγράμματα",
  "quiz.offer.testimonial.school.copy4": "«Η εξαγωγή για το λογιστήριο προέρχεται πλέον από τα ίδια αρχεία που χρησιμοποιούμε για συμφωνητικά και πληρωμές, οπότε το τέλος του μήνα έχει πολύ λιγότερες διορθώσεις.»",
  "quiz.offer.savings.eyebrow": "Εκτιμώμενη επίδραση στον χρόνο",
  "quiz.offer.savings.subtitle": "Εκτιμώμενη μείωση της επαναλαμβανόμενης διαχείρισης όταν αυτές οι διαδικασίες συνδέονται μέσω Tutlio.",
  "quiz.offer.savings.totalLabel": "πιθανή μείωση της επαναλαμβανόμενης διαχείρισης",
