  "quiz.offer.savings.solo.item1.body": "Η κοινή διαθεσιμότητα, τα επαναλαμβανόμενα μαθήματα και ένα ενιαίο ημερολόγιο μειώνουν την ανταλλαγή μηνυμάτων.",
  "quiz.offer.savings.solo.item2.value": "59%",
