  "schoolsLanding.heroSubtitle": "Σύστημα διαχείρισης για φροντιστήρια: καθηγητές, μαθητές, συμβάσεις, πληρωμές και αναφορές - όλα σε μία ασφαλή πλατφόρμα.",
  "schoolsLanding.heroCta": "Επικοινωνήστε μαζί μας",
  "schoolsLanding.heroSpotAria": "Προεπισκόπηση βασικών δυνατοτήτων",
  "schoolsLanding.heroSpot1Title": "Έξυπνο σχολικό ημερολόγιο",
  "schoolsLanding.heroSpot1Body": "Προγραμματίστε τα μαθήματα της ομάδας σας και αφήστε τις κρατήσεις να ακολουθούν τους δικούς σας κανόνες - ένα ξεκάθαρο σημείο για κάθε ώρα.",
  "schoolsLanding.heroSpot2Title": "Λίστα αναμονής",
  "schoolsLanding.heroSpot2Body": "Αφήστε τις λίστες σε χαρτί - αυτοματοποιήστε την αναμονή και καλύψτε τις θέσεις μετά από ακυρώσεις, με λιγότερη γραφειοκρατία και λιγότερα χαμένα έσοδα.",
  "schoolsLanding.heroMoreFeaturesCta": "Περισσότερες δυνατότητες",
  "schoolsLanding.trustText": "Φτιαγμένο για σχολεία που θέλουν να ψηφιοποιήσουν τη διοίκηση και τη διαχείριση των μαθημάτων.",
  "schoolsLanding.dashboardAlt": "Πίνακας διαχείρισης σχολείου της Tutlio",
  "schoolsLanding.heroLessonCount": "προγραμματισμένα μαθήματα. Ελάτε μαζί μας και κερδίστε χρόνο.",
  "schoolsLanding.stepsTitle": "Ξεκινήστε σε 3 απλά βήματα",
  "schoolsLanding.stepsDesc": "Ψηφιοποιήστε τη λειτουργία του σχολείου σας: στήστε τη δομή, ξεκινήστε τα μαθήματα και παρακολουθήστε τα αποτελέσματα - όλα από μία πλατφόρμα.",
  "schoolsLanding.step1Title": "Στήστε το σχολείο σας",
  "schoolsLanding.step1Desc": "Ρυθμίστε αντικείμενα, τμήματα, ρόλους καθηγητών και κανόνες μαθημάτων σύμφωνα με τις ανάγκες του σχολείου σας. Προσκαλέστε τους καθηγητές και αναθέστε αρμοδιότητες.",
  "schoolsLanding.step2Title": "Ξεκινήστε και τρέξτε τα μαθήματα",
  "schoolsLanding.step2Desc": "Προσκαλέστε μαθητές, δημοσιεύστε τα προγράμματα και κρατήστε τα πάντα συντονισμένα με αυτόματες υπενθυμίσεις και ειδοποιήσεις.",
  "schoolsLanding.step3Title": "Μετρήστε και βελτιώστε",
  "schoolsLanding.step3Desc": "Αξιοποιήστε τα δεδομένα παρουσιών και προόδου για να βελτιώσετε την ποιότητα των προγραμμάτων, να παρακολουθείτε τους δείκτες και να δίνετε σαφείς αναφορές στην ομάδα σας.",
  "schoolsLanding.featuresBadge": "Δυνατότητες",
  "schoolsLanding.featuresHeading": "Ό,τι χρειάζεται το σχολείο σας σε ",
  "schoolsLanding.featuresHighlight": "μία πλατφόρμα",
  "schoolsLanding.featuresSubtitle": "Από τον προγραμματισμό των μαθημάτων ως τις οικονομικές αναφορές - η Tutlio Schools δίνει στη διοίκησή σας τα εργαλεία για αποδοτική λειτουργία.",
  "schoolsLanding.feat.scheduling": "Προγραμματισμός μαθημάτων",
  "schoolsLanding.feat.schedulingDesc": "Διαχειριστείτε μαθήματα, ύλη και φόρτο των καθηγητών σε ένα ημερολόγιο.",
  "schoolsLanding.feat.schedulingHeading": "Σχεδιάστε και οργανώστε ",
  "schoolsLanding.feat.schedulingHighlight": "τα μαθήματά σας",
  "schoolsLanding.feat.schedulingB1": "Προγραμματίστε μεμονωμένα και επαναλαμβανόμενα μαθήματα για όλους τους καθηγητές σε ένα κοινό ημερολόγιο.",
  "schoolsLanding.feat.schedulingB2": "Ορίστε αυτόματα κανόνες κρατήσεων, κενά ανάμεσα στα μαθήματα και μέγιστο αριθμό μαθητών.",
  "schoolsLanding.feat.schedulingB3": "Δείτε ολόκληρο το πρόγραμμα του σχολείου ανά ημέρα, εβδομάδα ή μήνα - με όλους τους καθηγητές και τα αντικείμενα.",
  "schoolsLanding.feat.waitlist": "Διαχείριση καθηγητών",
  "schoolsLanding.feat.waitlistDesc": "Αναθέστε καθηγητές, διαχειριστείτε τον φόρτο τους και οργανώστε τα τμήματα.",
  "schoolsLanding.feat.waitlistHeading": "Διαχειριστείτε καθηγητές και ",
