  "schoolsLanding.feat.waitlistB2": "Παρακολουθήστε τον φόρτο και τη διαθεσιμότητα των καθηγητών σε όλο το σχολείο.",
  "schoolsLanding.feat.waitlistB3": "Η πρόσβαση με βάση τον ρόλο εξασφαλίζει ότι κάθε καθηγητής βλέπει μόνο τους δικούς του μαθητές και τα δικά του μαθήματα.",
  "schoolsLanding.feat.payments": "Οικονομικά και συμβάσεις",
