  "schoolsLanding.ctaBannerBtn": "Επικοινωνήστε μαζί μας",
  "schoolsLanding.faq.whatIsQ": "Τι είναι η Tutlio για τα σχολεία;",
  "schoolsLanding.faq.whatIsA": "Η Tutlio Schools είναι λογισμικό διαχείρισης για φροντιστήρια - πρόγραμμα καθηγητών, CRM μαθητών, συμβάσεις, πληρωμές και αναφορές σε μία πλατφόρμα.",
  "schoolsLanding.faq.whoForQ": "Σε ποιους απευθύνεται η Tutlio Schools;",
  "schoolsLanding.faq.whoForA": "Σε κέντρα ξένων γλωσσών, φροντιστήρια, ωδεία, προγράμματα προετοιμασίας για εξετάσεις και κάθε οργανισμό που συντονίζει πολλούς καθηγητές και μαθητές.",
  "schoolsLanding.faq.contractsQ": "Μπορούμε να διαχειριζόμαστε συμβάσεις και πληρωμές;",
  "schoolsLanding.faq.contractsA": "Ναι. Η πλατφόρμα υποστηρίζει πρότυπα συμβάσεων, ηλεκτρονική υπογραφή, δόσεις, πληρωμές μέσω Stripe και οικονομικές αναφορές.",
  "schoolsLanding.faq.pricingQ": "Πώς διαμορφώνεται η τιμή για τα σχολεία;",
  "schoolsLanding.faq.pricingA": "Τα σχολεία λαμβάνουν εξατομικευμένη τιμή ανάλογα με τον αριθμό των καθηγητών και τις ανάγκες τους. Επικοινωνήστε μαζί μας για προσφορά στα μέτρα σας.",
  "schoolsLanding.faq.trialQ": "Μπορούμε να δοκιμάσουμε πριν αγοράσουμε;",
  "schoolsLanding.faq.trialA": "Ναι - κλείστε μια δωρεάν συνάντηση και παρουσίαση. Θα σας δείξουμε πώς η Tutlio ταιριάζει στον τρόπο λειτουργίας του σχολείου σας.",
