  "landing.custom.sub": "Κάθε σχολείο και κάθε γραφείο λειτουργεί λίγο διαφορετικά. Όταν η τυπική ροή δεν ταιριάζει, προσαρμόζουμε την Tutlio στη δική σας διαδικασία - συνήθως σε εβδομάδες, όχι σε τρίμηνα. Μερικά από όσα έχουμε ήδη φτιάξει για πελάτες:",
