  "landing.custom.ex1Desc": "Ένα ιδιωτικό σχολείο ήθελε οι γονείς να υπογράφουν ηλεκτρονικά τις ετήσιες συμβάσεις, να πληρώνουν σε δόσεις και κάθε πληρωμή να εμφανίζεται σε εξαγωγή έτοιμη για το λογιστήριο. Σήμερα όλος ο κύκλος γίνεται μέσα στην Tutlio.",
  "landing.custom.ex2Title": "Κανόνες αμοιβής και προμήθειας καθηγητών",
  "landing.custom.ex2Desc": "Ένα γραφείο πληρώνει κάθε καθηγητή ανάλογα με το αντικείμενο και τον τύπο του μαθήματος, με προμήθεια της εταιρείας από πάνω. Μοντελοποιήσαμε τους κανόνες τους, ώστε οι μηνιαίες καταστάσεις των καθηγητών και τα τιμολόγια να δημιουργούνται αυτόματα.",
  "landing.custom.ex3Title": "Προσφορές προς τους γονείς με ένα κλικ",
  "landing.custom.ex3Desc": "Ένα σχολείο ήθελε να προτείνει πρόσθετα μαθήματα με email και να τα αποδέχονται οι γονείς με ένα μόνο κλικ - χωρίς λογαριασμό και χωρίς εκτυπώσεις. Η αποδοχή, η τιμολόγηση και η πρόσκληση στο πρώτο μάθημα γίνονται πλέον από μόνες τους.",
  "landing.custom.ex4Title": "Η ταυτότητά σας, στον ιστότοπό σας",
  "landing.custom.ex4Desc": "Ένας οργανισμός ήθελε το δικό του λογότυπο και χρώματα, καθώς και σύνδεση ενσωματωμένη στον ιστότοπό του, ώστε μαθητές και γονείς να μη νιώθουν ποτέ ότι τον εγκατέλειψαν. Σήμερα η Tutlio λειτουργεί με τη δική τους ταυτότητα.",
  "landing.custom.note": "Τίποτα από αυτά δεν είναι ξεχωριστή έκδοση. Κάθε προσαρμογή γίνεται μέρος του ίδιου προϊόντος που ήδη χρησιμοποιεί η ομάδα σας, με όλες τις μελλοντικές ενημερώσεις.",
  "landing.custom.cta": "Πείτε μας πώς δουλεύετε",
  "landing.custom.soloTitle": "Σας λείπει κάτι;",
  "landing.custom.soloNote": "Αναπτύσσουμε τακτικά λειτουργίες για μεμονωμένους πελάτες - από έναν κανόνα πληρωμής ως μια ολόκληρη ροή εργασίας. Πείτε μας τι θα σας γλίτωνε χρόνο.",
  "stats.cancellationPartTutor": "καθηγητής: {count}",
  "stats.cancellationPartAdmin": "διαχειριστής: {count}",
